using EduPlatform.Domain.Courses;
using EduPlatform.Domain.Reviews;
using EduPlatform.Domain.Common;
using EduPlatform.Infrastructure.Identity;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Microsoft.EntityFrameworkCore.Storage.ValueConversion;

namespace EduPlatform.Persistence.Configuration
{
    public class CourseConfiguration : IEntityTypeConfiguration<Course>
    {
        public void Configure(EntityTypeBuilder<Course> builder)
        {
            builder.ToTable("Courses");

            // Primary key
            builder.HasKey(c => c.Id);

            // Concurrency token (RowVersion) – required
            builder.Property(c => c.RowVersion)
                .IsRowVersion()
                .HasColumnName("RowVersion")
                .IsRequired();

            // Complex Money value object (Price + Currency)
            builder.ComplexProperty(c => c.Price, price =>
            {
                price.Property(p => p.Amount)
                    .HasColumnType("decimal(10,2)");

                price.Property(p => p.Currency)
                    .HasColumnType("char(3)");
            });


            // CourseSlug conversion
            builder.Property(c => c.Slug)
                .HasConversion(
                    v => v.Value,
                    v => new CourseSlug(v))
                .HasMaxLength(50)
                .IsRequired();

            // Other scalar columns
            builder.Property(c => c.Title).IsRequired();
            builder.Property(c => c.Description).IsRequired();

            // Enum to tinyint
            builder.Property(c => c.Status)
                .HasConversion<byte>()
                .HasColumnType("tinyint")
                .IsRequired();

            // Denormalized read columns
            var ratingConverter = new ValueConverter<RatingScore, decimal>(
                v => (decimal)v.Value,
                v => new RatingScore((double)v));

            builder.Property(c => c.AverageRating)
                .HasConversion(ratingConverter)
                .HasColumnType("decimal(2,1)")
                .HasDefaultValue(RatingScore.Min)
                .IsRequired();
            builder.Property(c => c.ReviewCount).IsRequired();
            builder.Property(c => c.EnrollmentCount).IsRequired();

            // Audit columns (required)
            builder.Property(c => c.CreatedAt)
                .HasColumnType("datetime2")
                .HasDefaultValueSql("SYSUTCDATETIME()")
                .IsRequired();

            builder.Property(c => c.UpdatedAt)
                .HasColumnType("datetime2")
                .HasDefaultValueSql("SYSUTCDATETIME()"); // nullable, no IsRequired()

            // Soft‑delete shadow property (only Courses)
            builder.Property<bool>("IsDeleted")
                .HasDefaultValue(false);
            builder.HasQueryFilter(c => EF.Property<bool>(c, "IsDeleted") == false);

            // Relationships
            builder.HasOne(c => c.Category)
                .WithMany(cat => cat.Courses)
                .HasForeignKey(c => c.CategoryId);

            builder.HasOne<ApplicationUser>()
                .WithMany()
                .HasForeignKey(c => c.InstructorId);

            // Indexes – exact names from the chapter
            builder.HasIndex(c => c.Slug)
                .IsUnique()
                .HasDatabaseName("UQ_Courses_Slug");

            builder.HasIndex(c => new { c.CategoryId, c.Status })
                .HasDatabaseName("IX_Courses_CategoryId_Status");

            builder.HasIndex(c => c.InstructorId)
                .HasDatabaseName("IX_Courses_InstructorId");

            builder.HasIndex(c => new { c.Status, c.CreatedAt })
                .IsDescending(false, true) // Status ASC, CreatedAt DESC
                .HasDatabaseName("IX_Courses_Status_CreatedAt_Desc");

            builder.HasIndex(c => c.EnrollmentCount)
                .IsDescending()
                .HasFilter("[Status] = 1")
                .HasDatabaseName("IX_Courses_EnrollmentCount_Desc");
        }
    }
